import { cx } from './cx';

/**
 * Brand wordmark. Assets are generated by `scripts/make-logo.py` (tight crop,
 * transparent background, exported at 3x for the display height).
 */
const variants = {
  sidebar: { src: '/brand/logo-sidebar.png', height: 'h-10' },
  topbar: { src: '/brand/logo-topbar.png', height: 'h-7' },
  signin: { src: '/brand/logo-signin.png', height: 'h-12' },
} as const;

export type LogoVariant = keyof typeof variants;

export function Logo({
  variant = 'signin',
  className,
}: {
  variant?: LogoVariant;
  className?: string;
}) {
  const v = variants[variant];
  return (
    <img
      src={v.src}
      alt="Assistance Ghana"
      draggable={false}
      className={cx(v.height, 'w-auto max-w-full select-none', className)}
    />
  );
}
